      // see documentdb-connection guidance
      maxPoolSize: 50,
      retryWrites: true,
      tls: true,
    }).then((m) => {
      console.log('Connected to DocumentDB:', dbName);
      return m;
    }).catch((err) => {
      console.error('Mongo connection error', err);
      throw err;
    });
  }
  return connectionPromise;
}

