{"path": "src/models/transaction.js", "content": "const { Schema } = require('mongoose');

const TransactionSchema = new Schema({
  accountId: { type: String, required: true, index: true },
  amount: { type: Number, required: true },
  type: { type: String, enum: ['credit', 'debit'], required: true },
  transactionRef: { type: String, required: true, unique: true },
  metadata: { type: Schema.Types.Mixed },
  schemaVersion: { type: Number, default: 1 }
}, { timestamps: { createdAt: 'createdAt', updatedAt: false } });

// prevent updates to transactions (immutable after creation). Mongoose does not
// have a global immutable flag for documents, but we can set individual paths
TransactionSchema.path('accountId').immutable(true);
TransactionSchema.path('amount').immutable(true);
TransactionSchema.path('type').immutable(true);
TransactionSchema.path('transactionRef').immutable(true);

// Compound index for recent activity queries
TransactionSchema.index({ accountId: 1, createdAt: -1 });

module.exports = { TransactionSchema };
"}

