    if (existing) {
      console.log('Skipping existing', a.accountId);
    } else {
      await Account.create(a);
      console.log('Created account', a.accountId);
    }
  }

  // Ensure indexes
  await Transaction.init();
  await Account.init();

  console.log('Seed complete');
  await disconnect();
}

